%
\begin{equation*}
\det \mathbf{F} = \det \mathbf{A} \cdot \det \mathbf{S} > 0,
\end{equation*}
%
establishing non-singularity of $\mathbf{F}$ and hence local identifiability. \qed


\section{Murphy--Topel Variance Correction}
\label{app:murphy_topel}

The three-stage G-MFRM procedure treats Stage~2 exposure estimates $\hat{e}_i$ as fixed in Stage~3, understating posterior uncertainty by ignoring estimation error in $\hat{e}_i$. We derive the Murphy--Topel correction \citep{murphy1985} adapted to the G-MFRM setting.

\paragraph{Setup.} Let $\boldsymbol{\alpha} = (e_1, \ldots, e_I)$ denote the Stage~2 parameters estimated from an independent dataset with log-likelihood $\ell_2(\boldsymbol{\alpha})$, and let $\boldsymbol{\psi} = (\boldsymbol{\theta}, \mathbf{c}, \mathbf{b}, \mathbf{d}, \boldsymbol{\tau})$ denote the Stage~3 parameters estimated with log-likelihood $\ell_3(\boldsymbol{\psi}; \hat{\boldsymbol{\alpha}})$, where $\hat{\boldsymbol{\alpha}}$ is plugged in as known.

\paragraph{Naive and Stage~2 variances.} The naive (uncorrected) variance of $\hat{\boldsymbol{\psi}}$ is
%
\begin{equation}
\mathbf{V}_3 = \left[-\frac{\partial^2 \ell_3}{\partial \boldsymbol{\psi}\, \partial \boldsymbol{\psi}^\top}\bigg|_{\hat{\boldsymbol{\psi}},\, \hat{\boldsymbol{\alpha}}}\right]^{-1},
\end{equation}
%
and the Stage~2 variance is
%
\begin{equation}
\mathbf{V}_2 = \left[-\frac{\partial^2 \ell_2}{\partial \boldsymbol{\alpha}\, \partial \boldsymbol{\alpha}^\top}\bigg|_{\hat{\boldsymbol{\alpha}}}\right]^{-1}.
\end{equation}

\paragraph{Cross-derivative matrix.} The coupling between stages is captured by the cross-derivative
%
\begin{equation}
\mathbf{C} = \frac{\partial^2 \ell_3}{\partial \boldsymbol{\psi}\, \partial \boldsymbol{\alpha}^\top}\bigg|_{\hat{\boldsymbol{\psi}},\, \hat{\boldsymbol{\alpha}}}.
\end{equation}
%
In the G-MFRM, non-zero entries of $\mathbf{C}$ arise from the contamination gating term $c_n \cdot e_i$. The key entry is
%
\begin{equation}
\frac{\partial^2 \ell_3}{\partial c_n\, \partial e_i} = \sum_{j=1}^{J} \frac{\partial^2 \ell_{nij}}{\partial \eta_{nij}^2} \cdot c_n,
\end{equation}
%
which is proportional to $c_n$: models with zero contamination contribute no cross-derivative. Similarly, $\partial^2 \ell_3 / (\partial \theta_n\, \partial e_i)$ involves only indirect coupling through the shared item observations. The correction is therefore concentrated on the contamination parameters of models with $c_n > 0$.

\paragraph{Corrected variance.} The Murphy--Topel corrected variance is
%
\begin{equation}
\label{eq:murphy_topel}
\mathbf{V}_{\mathrm{MT}} = \mathbf{V}_3 + \mathbf{V}_3\, \mathbf{C}\, \mathbf{V}_2\, \mathbf{C}^\top\, \mathbf{V}_3.
\end{equation}
%
The correction term $\mathbf{V}_3 \mathbf{C} \mathbf{V}_2 \mathbf{C}^\top \mathbf{V}_3$ is positive semi-definite, so $\mathbf{V}_{\mathrm{MT}} \succeq \mathbf{V}_3$: the corrected variance is always at least as large as the naive variance. The inflation is concentrated on $c_n$ for contaminated models and is negligible for $\theta_n$ when contamination is sparse, consistent with the empirical pattern in Table~\ref{tab:error_prop}.

\paragraph{Implementation.} We estimate $\mathbf{V}_2$ from the Stage~2 bootstrap and compute $\mathbf{C}$ via finite differences of the Stage~3 log-likelihood evaluated at perturbed $\hat{\boldsymbol{\alpha}}$ values. Corrected credible intervals are obtained by inflating Stage~3 posterior samples by $\sqrt{\mathrm{diag}(\mathbf{V}_{\mathrm{MT}}) / \mathrm{diag}(\mathbf{V}_3)}$.


\section{Ablation Study}
\label{app:ablation}

\begin{table}[h]
\centering
\small
\begin{tabular}{lccc}
\toprule
\textbf{Variant} & $\theta$-RMSE & $\tau$ & $c_n$-RMSE \\
\midrule
Full G-MFRM & 0.124 & 0.922 & 0.544 \\
$-$ Judge severity ($d_j$) & 0.126 & 0.920 & 0.568 \\
Binary gating & 0.138 & 0.909 & 0.739 \\
Staged estimation & 0.273 & 0.826 & 1.341 \\
\bottomrule
\end{tabular}
\caption{Ablation study on synthetic data ($N = 50$, $I = 100$, $J = 8$, 10 seeds; preliminary). Each row removes or modifies one component of the full G-MFRM. Staged estimation refers to fitting MFRM and contamination sequentially rather than jointly.}
\label{tab:ablation}
\end{table}

The ablation confirms that joint estimation is the primary contributor to G-MFRM's advantage: staged estimation increases $\theta$-RMSE by $2.2\times$ (from 0.124 to 0.273) and $c_n$-RMSE by $2.5\times$ (from 0.544 to 1.341), with $\tau$ dropping from 0.922 to 0.826. This degradation directly reflects the omitted variable bias characterized in Section~\ref{sec:confounding}: when contamination and judge effects are estimated sequentially, the first-stage estimates absorb the unmodeled facet.

Replacing continuous exposure $e_i \in [0,1]$ with binary gating ($e_i \in \{0, 1\}$) increases $c_n$-RMSE by 36\% (from 0.544 to 0.739), indicating that graded exposure modeling captures contamination magnitude more precisely than a binary flag. The effect on $\theta$-RMSE is moderate ($+$11\%), suggesting that the binary approximation still captures the dominant contamination signal but loses precision on partially exposed items.

Removing judge severity $d_j$ produces minimal degradation ($\theta$-RMSE $+$1.6\%, $\tau$ $-$0.2\%). Under the balanced design with $J = 8$ judges, severity effects are averaged out across the fully crossed matrix, reducing the marginal contribution of explicit $d_j$ estimation. We retain $d_j$ in the full model because (i) the MFRM facet specification is theory-driven rather than data-selected, (ii) the $d_j$ profile provides independent diagnostic value for judge calibration (e.g., Claude Opus $d_j = +0.60$ vs.\ Mistral $-0.74$ in the real-data evaluation), and (iii) unbalanced or sparse designs would amplify judge severity effects.


\section{Posterior Predictive Check}
\label{app:ppc}

Figure~\ref{fig:ppc} shows the posterior predictive distribution from 1{,}000 posterior draws over 5{,}661 observations. The predicted and observed response distributions are well-aligned (predicted mean win rate $0.593$ vs.\ observed $0.599$), with no systematic discrepancy across item difficulty or model ability levels.

\begin{figure}[h]
\centering
\includegraphics[width=0.8\columnwidth]{fig_ppc}
\caption{Posterior predictive check. Distribution of predicted (gray) and observed (black) response rates across all model--item--judge triplets. Mean predicted $= 0.593$, mean observed $= 0.599$.}
\label{fig:ppc}
\end{figure}


\section{Error Propagation Figure}
\label{app:error_prop_fig}

\begin{figure}[h]
\centering
\includegraphics[width=\columnwidth]{fig3_error_propagation}
\caption{Error propagation from Stage~2 exposure noise to Stage~3 parameter estimates. (a)~Ability RMSE ($\theta$) and (b)~contamination RMSE ($c_n$) as a function of exposure noise $\sigma_e$. The dashed vertical line marks $\sigma_{\mathrm{crit}} \approx 0.2$, below which degradation remains mild ($\theta$-RMSE $+$5.9\%, $c_n$-RMSE $+$7.9\%). Error bars show $\pm$1 std over 20 seeds. See Table~\ref{tab:error_prop} for numerical values.}
\label{fig:error_prop}
\end{figure}

